const slug=name=>name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
export const catalogSections = Object.freeze([
 {id:'components',name:'Components'}, {id:'chat',name:'Chat'}, {id:'patterns',name:'Patterns'},
]);
export const catalogComponentGroups = Object.freeze([
 {id:'buttons',name:'Buttons'}, {id:'dropdown',name:'Dropdown'},
 {id:'inputs',name:'Inputs'}, {id:'dates',name:'Date & Time'},
 {id:'container',name:'Cards & Containers'}, {id:'content',name:'Content'},
 {id:'feedback',name:'Feedback & Status'}, {id:'navigation',name:'Navigation'},
 {id:'overlay',name:'Popovers & Tooltips'}, {id:'table',name:'Table'},
 {id:'analytics',name:'Charts & Metrics'},
]);
const componentNavigationGroup=(id,family)=>{
 if(['button','button-group','icon-button','toggle-button','toggle-button-group'].includes(id))return 'buttons';
 if(['dropdown-menu','dropdown-menu-option','more-menu','selector','searchable-dropdown','complex-selector','multi-selector'].includes(id))return 'dropdown';
 if(['calendar','date-input','date-range-input','date-time-input','time-input'].includes(id))return 'dates';
 if(family==='forms')return 'inputs';
 if(id==='toast')return 'feedback';
 if(['list','metadata-list','overflow-list','table-selection-toolbar','tree-list','editable-table','report-table'].includes(id))return 'table';
 return catalogComponentGroups.some(group=>group.id===family)?family:null;
};
const sharedSurfacePolicy='DS2 standard single-line fields, dropdown field triggers and default buttons share a 40px height and 16px inline padding through control-height and control-padding-inline. Single-line dropdown options include their padding and border within the shared 40px minimum through border-box sizing. Native select pickers and MenuItem options use the same Body typography and option spacing. Chat navigation rows also use 40px; descriptions may grow. Dropdown and drawer option groups use a 2px row gap, including native wrapped menu rows. Icon fields reserve the icon plus the shared gap at that same edge inset. Compound fields own one outer height; multiline areas and documented compact controls retain their own layout. DS2 layout boundaries, cards and surface outlines use the quiet structural border role. Menus retain their semantic divider role, and table rows use their table-divider role without inset cell shadows. Fields and dropdown triggers keep their own component-specific default, hover, disabled, readonly and validation border roles in both modes; never force the field-border color onto every surface. Controls and popup surfaces have no box shadow, except the documented floating table-edit review surface, which uses the host semantic elevation shadow. The root theme owner reveals scroll thumbs during scrolling and fades them afterward, including owned portals. ScrollArea supplies draggable overlay thumbs without reserving vertical or horizontal gutters; List Page and the Scrollable Area example reuse it. Native scrolling, keyboard focus and forced-color scrollbars remain intact. New components reuse the shared owner without their own activity listeners.';
const focusPolicy='Design System 2.0 shows a focus indicator only during keyboard navigation, inset inside the component border. Pointer clicks, touch activation and selected states never add an outer ring or glow. Compound fields use one indicator on the field border.';
const ghostDropdownPolicy='In Design System 2.0, a ghost dropdown trigger stays visibly selected while its own menu is open. Use the native aria-expanded and aria-haspopup state, including Select target wrappers; dismissal clears this treatment without an extra focus ring or separate selection flag.';
const dropdownAnchoringIds=['dropdown-menu','dropdown-menu-option','more-menu','selector','searchable-dropdown','complex-selector','multi-selector','tokenizer','calendar','date-input','date-range-input','date-time-input','time-input','top-nav-mega-menu','top-nav-menu','full-screen'];
const dropdownAnchoringPolicy='Field dropdowns, action menus, searchable lists, multi-selects, token editors and calendar pickers prefer below-start with an 8px edge-to-edge gap (spacing-2), including after a native collision flip above. If neither vertical side fits, retain the native viewport-safe flip or shift instead of clipping the panel. Keep the panel anchored while its container scrolls; constrain long lists to the viewport and scroll their contents. Native select pickers retain browser anchoring with position-try-order normal and the same logical block margin. Forge anchored panels reuse anchoredPopoverProps and FLOATING_PANEL_GAP; do not add per-field offsets or another positioning listener. Nested menus open beside their parent option and bottom-anchored composer or navigation panels retain their documented direction, using the same shared gap. Preserve native dismissal, selection, keyboard focus and focus return; test available space above and below in both modes.';
const dropdownAppearancePolicy='DS2 dropdown panels and options have no shadows in light or dark mode. Use a subtle semantic border and the shared selected background and foreground without a decorative checkmark. Retain native selection semantics, content icons and the keyboard-only inset focus indicator.';
const contentLoadingPolicy='Use the shared Skeleton for pending DS2 content, including table rows and asynchronous filter options. Open the surface immediately and read its native source state; keep known choices and draft selections during refresh. Announce loading once and hide decorative shapes. A recoverable option-load failure uses the host Toast and native Retry, with keyboard focus retained on the existing search field. Loading, empty and failed results remain distinct; do not create a second request, cache or loading flag.';
export const componentCatalog = Object.freeze(Object.entries(rows).flatMap(([family,entries])=>entries.map(([name,variants,implementation,contractName,description,usage,avoid,reference=true])=>{
 const id=slug(name), contract=contracts[contractName];
 return Object.freeze({id,name,family,section:['chat','patterns'].includes(family)?family:'components',navigationGroup:componentNavigationGroup(id,family),description,implementation,contractName,reference,variants:variants.split(','),...contract,...overrides[id],anatomy:anatomyById[id]||contract.anatomy,usage,avoid,
   ...(['table','list-page','drawer','skeleton','data-state'].includes(id)?{behavior:[...(overrides[id]?.behavior||contract.behavior),contentLoadingPolicy]}:{}),
   ...(dropdownAnchoringIds.includes(id)?{behavior:[...(overrides[id]?.behavior||contract.behavior),dropdownAnchoringPolicy],tokens:[...new Set([...(overrides[id]?.tokens||contract.tokens),'spacing-2'])]}:{}),
   kind:family==='patterns'?'pattern':implementation.includes('coverage gap')?'gap':/recipe|composition/i.test(implementation)?'recipe':'component',
   deprecated:id==='bottom-sheet-switcher',href:`#components/${id}`,
   accessibility:`${overrides[id]?.accessibility||'Provide a useful accessible name and retain the underlying semantic element. Theme color never replaces a written label.'} ${focusPolicy} ${ghostDropdownPolicy} ${sharedSurfacePolicy}${['menu','select','date'].includes(contractName)?` ${dropdownAppearancePolicy}`:''}${dropdownAnchoringIds.includes(id)?` ${dropdownAnchoringPolicy}`:''}`,
 });
})));
export const referenceComponents=Object.freeze(componentCatalog.filter(item=>item.reference));
export const findComponent=id=>componentCatalog.find(item=>item.id===id);
export const filterCatalog=(query='',family='all')=>{
 const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
 return componentCatalog.filter(item=>(family==='all'||item.family===family||item.section===family)&&words.every(word=>[item.name,item.family,item.section,item.description,item.implementation,...item.variants].join(' ').toLowerCase().includes(word)));
};
